Q() { docker exec -i xnova-database psql -U postgres -d postgres -At -c "$1" < /dev/null; }
Q "select table_name, string_agg(column_name||':'||data_type||':'||coalesce(column_default,''), ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('building_queue','shipyard_queue','research_queue','market_listings','debris_fields','referral_commissions','planet_defenses','planet_ships','defense_types') group by 1"
Q "select attname, attgenerated, attidentity from pg_attribute where attrelid in ('public.building_queue'::regclass,'public.shipyard_queue'::regclass) and attnum>0 and (attgenerated<>'' or attidentity<>'')"
Q "select prosrc from pg_proc where proname='_colony_listed_since'"
Q "select oid::regprocedure, pg_get_function_result(oid) from pg_proc where proname in ('validate_ship_requirements','validate_defense_requirements','fleet_calc_distance','fleet_calc_slowest_speed','fleet_calc_flight_time','fleet_calc_fuel','get_user_daily_mission_speed_bonus','is_user_plus','has_active_officer','battle_units_diff','check_moon_creation','calculate_and_sync_resources_internal','apply_vip_time_bonus','_colony_listed_since','get_live_tung_price_usd')"
